checks.run:
node -e '
const {execFileSync}=require("child_process")
const {existsSync,mkdtempSync,readFileSync,writeFileSync}=require("fs")
const {createHash}=require("crypto")
const {tmpdir}=require("os")
const {join}=require("path")
const shipped="wip/review-gate/RV-F12345.envelope.json"
const digest=()=>existsSync(shipped)?createHash("sha256").update(readFileSync(shipped)).digest("hex"):"absent"
const before=digest()
const scratch=mkdtempSync(join(tmpdir(),"rg-attest-probe-"))
const probe=join(scratch,"probe.claims.json")
writeFileSync(probe,JSON.stringify({task_id:"RV-PROBE",role:"reviewer",claims:[{id:"P1",severity:"high",statement:"trivial probe claim",checks:[{kind:"command",run:"node --version",expect_exit:0}]}]}))
const out=execFileSync(process.execPath,["scripts/review-gate.mjs","--checklist",probe,"--attest","--quiet"],{encoding:"utf8",env:{...process.env,REVIEW_GATE_ATTEST_DIR:scratch}})
const pointer=JSON.parse(out).artifact.path
if(!pointer.startsWith(scratch))throw new Error("default path escaped REVIEW_GATE_ATTEST_DIR: "+pointer)
if(!existsSync(join(scratch,"RV-PROBE.envelope.json")))throw new Error("no artefact written into REVIEW_GATE_ATTEST_DIR")
if(digest()!==before)throw new Error("a gate run changed the shipped artefact")
console.log("redirection honoured; shipped artefact stable "+before.slice(0,12))
'

node -e '
const fs=require("fs")
const cfg=JSON.parse(fs.readFileSync("opencode.json","utf8"))
const bad=Object.entries(cfg.agents).filter(([,a])=>a.request).map(([k])=>k)
if(bad.length)throw new Error("inert request.body still on: "+bad.join(", "))
const roster=["architect","researcher","reviewer","fact-checker","build","ui","artist","coder"]
const missing=roster.filter(n=>typeof (cfg.agents[n]||{}).temperature!=="number")
if(missing.length)throw new Error("no top-level temperature on: "+missing.join(", "))
const files=fs.readdirSync(".opencode/agents").filter(n=>n.endsWith(".md"))
const inert=files.filter(n=>fs.readFileSync(".opencode/agents/"+n,"utf8").includes("action: execute"))
if(inert.length)throw new Error("inert execute permission still in: "+inert.join(", "))
console.log("no inert agent config; "+roster.length+" agents on top-level temperature ("+roster.map(n=>n+"="+cfg.agents[n].temperature).join(" ")+"), "+files.length+" agent files clean")
'
